// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, uint256 blockNum) public {
        // admissible: timestamps after the constant 10, so the mutant can pass the require
        ts = bound(ts, 11, type(uint48).max);
        blockNum = bound(blockNum, 0, type(uint48).max);
        vm.roll(blockNum);

        address actor = address(0xA11CE);
        vm.deal(actor, 10 ether);

        // first call at time ts: succeeds for both P and M (pastBlockTime starts at 0)
        vm.warp(ts);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call should succeed");

        // second call at the SAME timestamp ts:
        // in P, pastBlockTime == ts, so require(block.timestamp > pastBlockTime) fails -> reverts
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // general rule: a second call in the same block/timestamp must always revert
        assertTrue(!ok2, "second call at the same timestamp must revert");
    }
}
